"""Author the fixture's geometric BMPs using only Python's standard library.
These intentionally simple diagnostic assets contain no imported game art or fonts.
"""
from pathlib import Path
import struct
import math

ROOT = Path(__file__).parent / 'images'
ROOT.mkdir(exist_ok=True)

def canvas(w, h, color=(0,0,0,0)):
    return [[color for _ in range(w)] for _ in range(h)]

def rect(p, x0, y0, x1, y1, color):
    for y in range(max(0,y0), min(len(p),y1)):
        for x in range(max(0,x0), min(len(p[0]),x1)):
            p[y][x] = (*color,255) if len(color)==3 else color

def save(name, p):
    h,w=len(p),len(p[0])
    pixels=bytes(v for row in reversed(p) for r,g,b,a in row for v in (b,g,r,a))
    # BITMAPV4HEADER declares BGRA masks so transparent geometry remains transparent.
    dib=struct.pack('<IiiHHIIiiII',108,w,h,1,32,3,len(pixels),2835,2835,0,0)
    dib+=struct.pack('<IIIII',0x00ff0000,0x0000ff00,0x000000ff,0xff000000,0x73524742)
    dib+=bytes(48)
    (ROOT/(name+'.bmp')).write_bytes(struct.pack('<2sIHHI',b'BM',14+108+len(pixels),0,0,122)+dib+pixels)

