def label(name,text,scale=2,color=(219,232,218)):
    p=canvas(max(1,len(text)*6*scale),7*scale)
    for i,ch in enumerate(text):
        if ch==' ':continue
        for y,row in enumerate(G[ch]):
            for x,pixel in enumerate(row):
                if pixel=='1':rect(p,(i*6+x)*scale,y*scale,(i*6+x+1)*scale,(y+1)*scale,color)
    save(name,p)
for name,text in [('title','VILLAGE DEFENSE'),('altar_label','ALTAR'),('tree_label','TREE'),('wave_label','WAVE'),('gather_label','SUPPLIES'),('next_label','NEXT WAVE'),('attack_label','HOLD SPACE TO ATTACK'),('controls','ARROWS MOVE   SPACE ATTACK   R RESTART'),('won','VILLAGE SAVED'),('lost','ALTAR FALLEN'),('goal','DEFEND THREE WAVES OR BREAK THE TREE')]:label(name,text,2 if name not in ['won','lost'] else 4)
for i in range(10):label('digit_'+str(i),str(i),2)
